<script setup lang="ts">
import { reactive,ref,watch } from 'vue'
import {exportRows,downloadCsv} from '../utils/export'
import { http } from '../api/http'
import PrivateUpload from './PrivateUpload.vue'
import RemoteSelect from './RemoteSelect.vue'
import type {Row,Definition} from '../shared/records'
const props=defineProps<{definition:Definition}>()
const exporting=ref(false)
const rows=ref<Row[]>([]),total=ref(0),page=ref(1),query=ref(''),loading=ref(false),saving=ref(false),dialog=ref(false),error=ref(''),success=ref(''),current=ref<number|null>(null),form=reactive<Row>({}),options=reactive<Record<string,Row[]>>({})
let generation=0
async function load(){const request=++generation;loading.value=true;error.value='';try{const params:Row={page:page.value,size:20};if(props.definition.search!=='')params[props.definition.search??'keyword']=query.value;const data=await http.get<never,any>(props.definition.endpoint,{params});if(request!==generation)return;if(Array.isArray(data)){const needle=query.value.trim().toLocaleLowerCase();const filtered=needle?data.filter(row=>props.definition.columns.some(([key])=>display(row[key],key).toLocaleLowerCase().includes(needle))):data;total.value=filtered.length;page.value=Math.min(page.value,Math.max(1,Math.ceil(total.value/20)));rows.value=filtered.slice((page.value-1)*20,page.value*20)}else{rows.value=data.records??[];total.value=data.total??0}}catch(e){if(request===generation){error.value=(e as Error).message;rows.value=[];total.value=0}}finally{if(request===generation)loading.value=false}}

async function exportAll(){if(exporting.value)return;exporting.value=true;error.value='';try{const definition=props.definition,needle=query.value.trim().toLocaleLowerCase(),params:Row={};if(definition.search!=='')params[definition.search??'keyword']=query.value;const data=await exportRows(definition.endpoint,params,row=>!needle||definition.columns.some(([key])=>display(row[key],key).toLocaleLowerCase().includes(needle)));downloadCsv(definition.title,definition.columns.map(([,label])=>label),data.map(row=>definition.columns.map(([key])=>display(row[key],key))));success.value=`已导出 ${data.length} 条记录`}catch(e){error.value=(e as Error).message}finally{exporting.value=false}}
async function edit(row?:Row){try{error.value='';current.value=row?.id??null;const detail=row&&props.definition.detail!==''?await http.get<never,Row>(`${props.definition.detail??props.definition.endpoint}/${row.id}`):row??{};Object.keys(form).forEach(k=>delete form[k]);for(const field of props.definition.fields??[]){form[field.key]=detail[field.key]??field.initial??(field.type==='multi'?[]:field.type==='check'?false:'');if(field.type==='datetime-local'&&form[field.key]){const d=new Date(form[field.key]);form[field.key]=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}if(field.type==='files'&&!Array.isArray(form[field.key]))form[field.key]=form[field.key]?[form[field.key]]:[];if(field.type==='tags')form[field.key]=Array.isArray(form[field.key])?form[field.key].join('，'):form[field.key];}dialog.value=true}catch(e){error.value=(e as Error).message}}
async function save(){if(saving.value)return;saving.value=true;error.value='';try{const body:Row={};for(const field of props.definition.fields??[]){const value=form[field.key];if(value===''||value===null||value===undefined)continue;body[field.key]=field.type==='datetime-local'?new Date(String(value)).toISOString():field.type==='tags'?String(value).split(/[,，]/).map(s=>s.trim()).filter(Boolean):value}if(props.definition.save)await props.definition.save(body,current.value);else if(current.value)await http.put(`${props.definition.endpoint}/${current.value}`,body);else await http.post(props.definition.endpoint,body);dialog.value=false;if(!current.value&&props.definition.search!==''&&(body.name||body.username)){page.value=1;query.value=String(body.name||body.username)}success.value='已保存';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function action(method:string,path:string,body?:Row){try{error.value='';await http.request({method,url:path,data:body});success.value='操作成功';await load()}catch(e){error.value=(e as Error).message}}
function display(value:any,key?:string):string{if(key==='businessStatus')return value==='OPEN'?'营业中':'暂停营业';if(key==='deliveryStatus')return ({PENDING:'待配送',OUT_FOR_DELIVERY:'配送中',DELIVERED:'已送达'} as Row)[String(value)]??String(value);if(key?.endsWith('At')&&typeof value==='string'&&/^\d{4}-\d{2}-\d{2}T.*Z$/.test(value)&&Number.isFinite(Date.parse(value)))return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'medium',hour12:false}).format(new Date(value));if(value===null||value===undefined)return'—';if(typeof value==='boolean')return value?'是':'否';if(Array.isArray(value))return value.map(v=>typeof v==='object'?(v.dishNameSnapshot?v.dishNameSnapshot+' × '+v.qty:display(v)):String(v)).join('、');if(typeof value==='object')return Object.values(value).map(v=>display(v)).filter(v=>v!=='—').join('；');return ({ACTIVE:'启用',DISABLED:'停用',OPEN:'待受理',CLOSED:'暂停营业',PENDING:'待审核',APPROVED:'已通过',REJECTED:'已驳回',REVOKED:'已撤回',DRAFT:'草稿',SUBMITTED:'已上报',PUBLISHED:'已发布',AVAILABLE:'可售',OFF_SHELF:'已下架',PENDING_PAYMENT:'待支付',PAID:'已支付',PREPARING:'备餐中',READY:'待取餐',COMPLETED:'已完成',CANCELLED:'已取消',CANCEL_REQUESTED:'申请取消',REFUND_PENDING:'退款处理中',REFUNDED:'已退款',REFUND_FAILED:'退款失败',PENDING_REVIEW:'待审核',OUT_FOR_DELIVERY:'配送中',DELIVERED:'已送达',IN_PROGRESS:'处理中',RESOLVED:'已办结',ESCALATED:'已升级',LUNCH:'午餐',DINNER:'晚餐',DINE_IN:'堂食',TAKEOUT:'外带',DELIVERY:'配送',GENERAL:'一般公告',CLOSURE:'停餐通知',ACTIVITY:'活动通知',IMPORTANT:'重要通知',FEEDBACK:'意见建议',COMPLAINT:'投诉'} as Row)[String(value)]??String(value)}
watch(()=>props.definition,()=>{page.value=1;query.value='';void load()},{immediate:true})
defineExpose({load,edit,action,error})
</script>
<template><section><p class="eyebrow">社区助餐服务</p><h1>{{definition.title}}</h1><slot name="intro"/>
 <el-alert v-if="error" :title="error" type="error" :closable="false" role="alert"/><el-alert v-if="success" :title="success" type="success" :closable="false"/>
 <div class="toolbar"><el-input v-if="definition.search!==''" v-model="query" aria-label="搜索" placeholder="输入关键词" @keyup.enter="page=1;load()"/><el-button @click="page=1;load()">查询</el-button><el-button v-if="definition.fields" type="primary" @click="edit()">新增</el-button><el-button :loading="exporting" @click="exportAll">导出 CSV</el-button><slot name="tools" :refresh="load"/></div>
 <el-table v-loading="loading" :data="rows" stripe empty-text="暂无记录"><el-table-column v-for="[key,label] in definition.columns" :key="key" :label="label" min-width="120"><template #default="{row}">{{display(row[key],key)}}</template></el-table-column><el-table-column v-if="definition.fields||$slots.actions" label="操作" min-width="240"><template #default="{row}"><el-button v-if="definition.fields&&!definition.createOnly" link type="primary" @click="edit(row)">编辑</el-button><slot name="actions" :row="row" :refresh="load" :action="action"/></template></el-table-column></el-table>
 <div class="toolbar"><span>共 {{total}} 条</span><el-button :disabled="page===1" @click="page--;load()">上一页</el-button><span>{{page}}</span><el-button :disabled="page*20>=total" @click="page++;load()">下一页</el-button></div>
 <el-dialog v-model="dialog" :title="(current?'编辑':'新增')+definition.title" width="min(660px,94vw)"><el-alert v-if="error" :title="error" type="error" :closable="false"/><form class="form-stack" @submit.prevent="save"><template v-for="field in definition.fields" :key="field.key"><label :for="'field-'+field.key">{{field.label}}</label><RemoteSelect v-if="field.source" :id="'field-'+field.key" v-model="form[field.key]" :source="field.source" :label="field.label" :multiple="field.type==='multi'"/><el-select v-else-if="['multi','select'].includes(field.type??'')" :id="'field-'+field.key" v-model="form[field.key]" :multiple="field.type==='multi'" clearable :aria-label="field.label"><el-option v-for="option in field.options??options[field.key]??[]" :key="String(option.value)" :label="option.label" :value="option.value"/></el-select><PrivateUpload v-else-if="field.type==='files'" v-model="form[field.key]" :purpose="field.purpose??'SUBSIDY'"/><el-checkbox v-else-if="field.type==='check'" v-model="form[field.key]">已确认</el-checkbox><el-input v-else :id="'field-'+field.key" v-model="form[field.key]" :type="['number','date','password','textarea','datetime-local'].includes(field.type??'')?field.type:'text'" :show-password="field.type==='password'" :step="field.type==='number'?'any':undefined"/></template><el-button native-type="submit" type="primary" :loading="saving">保存</el-button></form></el-dialog>
</section></template>
